import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Usf Panel: túneles contra la censura","description":"Construir paneles proxy para un entorno donde el bloqueo es una carrera armamentista — la historia y filosofía detrás de Usf Panel y su familia.","frontmatter":{"title":"Usf Panel: túneles contra la censura","description":"Construir paneles proxy para un entorno donde el bloqueo es una carrera armamentista — la historia y filosofía detrás de Usf Panel y su familia."},"headers":[],"relativePath":"es/vibe-stories/story-3/index.md","filePath":"es/vibe-stories/story-3/index.md"}`),a={name:`es/vibe-stories/story-3/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="usf-panel-tuneles-contra-la-censura" tabindex="-1">Usf Panel: túneles contra la censura <a class="header-anchor" href="#usf-panel-tuneles-contra-la-censura" aria-label="Permalink to “Usf Panel: túneles contra la censura”">​</a></h1><p>Algunos programas son una conveniencia; otros son una línea de vida. Mi familia de paneles — <strong>Usf Panel</strong>, usf-edge, edge-pp, Render-usf — es del segundo tipo. Gestionan túneles y suscripciones VLESS para personas cuyo internet se filtra con regularidad, incluida la mía.</p><h2 id="el-modelo-de-amenaza-es-real" tabindex="-1">El modelo de amenaza es real <a class="header-anchor" href="#el-modelo-de-amenaza-es-real" aria-label="Permalink to “El modelo de amenaza es real”">​</a></h2><p>Construir para redes censuradas cambia cada decisión de diseño. Las plataformas mismas se vuelven superficies de ataque: cuando un proveedor empieza a banear en masa cargas de proxy, tus usuarios quedan a oscuras — por eso cada panel que envío se despliega en <strong>cinco plataformas con un comando</strong>, y las variantes de borde guardan estado en Cloudflare KV a través de 300+ PoPs donde no hay servidor que confiscar.</p><h2 id="ingenieria-bajo-fuego" tabindex="-1">Ingeniería bajo fuego <a class="header-anchor" href="#ingenieria-bajo-fuego" aria-label="Permalink to “Ingeniería bajo fuego”">​</a></h2><ul><li><strong>Los enlaces de suscripción</strong> deben regenerarse limpiamente en Clash, v2ray y sing-box — un formato roto significa un usuario varado.</li><li><strong>Las cuotas multiusuario</strong> evitan que un usuario pesado exponga a todos.</li><li><strong>El endurecimiento del admin</strong> — token + 2FA — porque el panel mismo es el blanco más jugoso.</li><li><strong>Simulacros de migración</strong> — practico los movimientos de plataforma a plataforma antes de necesitarlos, no durante una caída.</li></ul><p>La filosofía completa está en la sección de <a href="/Usf/es/about/networking/">redes</a>; los detalles del buque insignia en <a href="/Usf/es/projects/usf-panel/">Usf Panel</a>. La historia se resume en: trata el acceso a la información como infraestructura crítica, e ingeniérselo con ese respeto.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};